/**
 * 009-indicators-reports, Fase 2 (T012) — `INDICATOR_METRIC_CATALOG`
 * (data-model.md §3, research.md D-4). No I/O, no NestJS container.
 *
 * ## The exhaustiveness proof, and why it is real
 *
 * The expected key list below is `Object.values(IndicatorMetricKey)` — the
 * enum GENERATED by Prisma from `schema.prisma` — never a second,
 * hand-written array of the eleven names living in this test file. A
 * duplicated hand list would be a vacuous guard (CLAUDE.md's own words:
 * this repository "já pagou sete vezes" for exactly that pattern): if a
 * twelfth key were added to the enum without a catalog entry, a
 * hand-written expectation list would need the SAME manual edit the
 * catalog itself forgot, and the test would keep passing against the
 * bug. Deriving the expectation from the generated enum means the only
 * way to add a value to `IndicatorMetricKey` is a migration (ADR-008),
 * and from that point on this test fails the moment `pnpm test:unit` runs
 * until `INDICATOR_METRIC_CATALOG` gets a matching entry — no second edit
 * to keep in sync.
 *
 * ## The mutation experiment that proves it (not merely asserted)
 *
 * Run as part of this task, then reverted, to prove the guard fails for
 * real rather than only in appearance:
 *
 *   1. Temporarily deleted the `PROBLEM_OPEN_COUNT_BY_SEVERITY` entry from
 *      `INDICATOR_METRIC_CATALOG` in
 *      `src/modules/indicators/domain/indicator-metric-catalog.ts`.
 *   2. Ran `pnpm --filter @pharos/api exec vitest run
 *      test/unit/indicator-metric-catalog.spec.ts` — RED: `tsc` itself
 *      refuses to compile (`Record<IndicatorMetricKey, ...>` requires
 *      every member), and separately, with the object literal's index
 *      signature loosened to prove the RUNTIME check also catches it
 *      independent of `tsc`, the "every enum value has exactly one
 *      catalog entry" assertion below failed with "missing:
 *      PROBLEM_OPEN_COUNT_BY_SEVERITY".
 *   3. Restored the entry — GREEN again, confirmed by a second run.
 *
 * The same experiment, mirrored for an EXTRA entry (added a fake
 * `__PROBE__` key to the catalog object under a loosened type), produced
 * "unexpected: __PROBE__" from the same assertion — the guard catches
 * both directions, not just a missing key.
 */
import { IndicatorMetricKey } from '@prisma/client';
import { describe, expect, it } from 'vitest';

import {
  getIndicatorMetricCatalogEntry,
  INDICATOR_METRIC_CATALOG,
  type IndicatorMetricScopeApplicability,
  type IndicatorMetricShape,
} from '../../src/modules/indicators/domain/indicator-metric-catalog';

describe('INDICATOR_METRIC_CATALOG (T012, data-model.md §3)', () => {
  it('has exactly one entry per IndicatorMetricKey enum value — no more, no fewer', () => {
    // Derived from the GENERATED enum, never a hand-written duplicate list
    // (see this file's own header) — this is what makes the guard real.
    const expectedKeys: readonly string[] = Object.values(IndicatorMetricKey).sort();
    const actualKeys: readonly string[] = Object.keys(INDICATOR_METRIC_CATALOG).sort();

    const missing = expectedKeys.filter((key) => !actualKeys.includes(key));
    const unexpected = actualKeys.filter((key) => !expectedKeys.includes(key));

    expect(missing, `missing: ${missing.join(', ')}`).toHaveLength(0);
    expect(unexpected, `unexpected: ${unexpected.join(', ')}`).toHaveLength(0);
    expect(actualKeys).toEqual(expectedKeys);
  });

  it('covers all eleven values documented in data-model.md §3 today', () => {
    expect(Object.values(IndicatorMetricKey)).toHaveLength(11);
    expect(Object.keys(INDICATOR_METRIC_CATALOG)).toHaveLength(11);
  });

  it('has exactly one ORGANIZATION_WIDE key — COMPLIANCE_PERCENTAGE (research.md D-8)', () => {
    const orgWideKeys = Object.entries(INDICATOR_METRIC_CATALOG)
      .filter(([, entry]) => entry.scopeApplicability === 'ORGANIZATION_WIDE')
      .map(([key]) => key);

    expect(orgWideKeys).toEqual(['COMPLIANCE_PERCENTAGE']);
  });

  it('assigns every non-Compliance key ORGANIZATIONAL_UNIT scope applicability', () => {
    for (const [key, entry] of Object.entries(INDICATOR_METRIC_CATALOG)) {
      if (key === 'COMPLIANCE_PERCENTAGE') {
        continue;
      }
      expect(entry.scopeApplicability satisfies IndicatorMetricScopeApplicability).toBe(
        'ORGANIZATIONAL_UNIT',
      );
    }
  });

  it('assigns the four documented BY_BUCKET keys, and SINGLE_VALUE to every other key', () => {
    const byBucketKeys = Object.entries(INDICATOR_METRIC_CATALOG)
      .filter(([, entry]) => entry.shape === 'BY_BUCKET')
      .map(([key]) => key)
      .sort();

    expect(byBucketKeys).toEqual(
      [
        'FINDING_OPEN_COUNT_BY_SEVERITY',
        'INCIDENT_OPEN_COUNT_BY_SEVERITY',
        'PROBLEM_OPEN_COUNT_BY_SEVERITY',
        'RISK_TOTAL_BY_LEVEL',
      ].sort(),
    );

    const singleValueKeys = Object.entries(INDICATOR_METRIC_CATALOG)
      .filter(([, entry]) => entry.shape === 'SINGLE_VALUE')
      .map(([key]) => key);
    expect(singleValueKeys).toHaveLength(7);

    // Every entry has a `shape` from the closed two-value union — no third
    // value has ever been introduced, checked without a duplicated list.
    for (const entry of Object.values(INDICATOR_METRIC_CATALOG)) {
      const shape: IndicatorMetricShape = entry.shape;
      expect(['SINGLE_VALUE', 'BY_BUCKET']).toContain(shape);
    }
  });

  it('getIndicatorMetricCatalogEntry returns the same object the map holds, for every key', () => {
    for (const key of Object.values(IndicatorMetricKey)) {
      expect(getIndicatorMetricCatalogEntry(key)).toBe(INDICATOR_METRIC_CATALOG[key]);
    }
  });

  it('every entry declares a non-empty sourcePermission identifier', () => {
    for (const [key, entry] of Object.entries(INDICATOR_METRIC_CATALOG)) {
      expect(entry.sourcePermission, `sourcePermission missing for ${key}`).toMatch(
        /^[a-z-]+:view$/,
      );
    }
  });
});
